ansible/roles/core/tasks/main.json:
[
  {
    "ansible.builtin.package": {
      "name": [
        "docker.io",
        "docker-compose"
      ],
      "state": "present",
      "update_cache": true
    },
    "name": "Install the container engine"
  },
  {
    "ansible.builtin.systemd": {
      "enabled": true,
      "name": "docker",
      "state": "started"
    },
    "name": "Start the container engine"
  },
  {
    "ansible.builtin.file": {
      "mode": "0700",
      "path": "/opt/bromigos-lab",
      "state": "directory"
    },
    "name": "Make the lab folder"
  },
  {
    "ansible.builtin.copy": {
      "dest": "/opt/bromigos-lab/",
      "directory_mode": "0755",
      "mode": "0644",
      "src": "{{ playbook_dir }}/../../compose/"
    },
    "name": "Copy the reviewed container definitions"
  },
  {
    "ansible.builtin.shell": {
      "chdir": "/opt/bromigos-lab",
      "cmd": "if docker compose version >/dev/null 2>&1; then docker compose up -d; else docker-compose up -d; fi"
    },
    "changed_when": false,
    "name": "Start selected services without deleting data"
  }
]

ansible/roles/helm/tasks/main.json:
[
  {
    "ansible.builtin.get_url": {
      "checksum": "sha256:86584a54def73570558f66f5111cc53dfed56689637ae32c1201205d494f54fb",
      "dest": "/opt/bromigos-helm.tar.gz",
      "mode": "0644",
      "url": "https://get.helm.sh/helm-v4.3.0-linux-amd64.tar.gz"
    },
    "name": "Download pinned Helm"
  },
  {
    "ansible.builtin.unarchive": {
      "creates": "/opt/linux-amd64/helm",
      "dest": "/opt",
      "remote_src": true,
      "src": "/opt/bromigos-helm.tar.gz"
    },
    "name": "Unpack Helm"
  },
  {
    "ansible.builtin.copy": {
      "dest": "/usr/local/bin/helm",
      "mode": "0755",
      "remote_src": true,
      "src": "/opt/linux-amd64/helm"
    },
    "name": "Install Helm"
  },
  {
    "ansible.builtin.file": {
      "mode": "0700",
      "path": "/opt/bromigos-lab/helm",
      "state": "directory"
    },
    "name": "Make the values folder"
  },
  {
    "ansible.builtin.copy": {
      "dest": "/opt/bromigos-lab/helm/vault.yaml",
      "mode": "0600",
      "src": "{{ playbook_dir }}/../../helm/vault/values.yaml"
    },
    "name": "Copy vault values"
  },
  {
    "ansible.builtin.command": {
      "argv": [
        "helm",
        "status",
        "vault",
        "--namespace",
        "vault",
        "--output",
        "json"
      ]
    },
    "changed_when": false,
    "environment": {
      "KUBECONFIG": "/etc/rancher/k3s/k3s.yaml"
    },
    "failed_when": false,
    "name": "Read vault release ownership",
    "register": "existing_release"
  },
  {
    "ansible.builtin.assert": {
      "fail_msg": "This Helm release belongs to another installer; use a fresh namespace or cluster",
      "that": [
        "existing_release.rc != 0 or (existing_release.stdout | from_json).info.description == 'bromigos-lab-provision'"
      ]
    },
    "name": "Refuse to take over an existing vault release"
  },
  {
    "ansible.builtin.command": {
      "argv": [
        "helm",
        "upgrade",
        "--install",
        "vault",
        "vault",
        "--description",
        "bromigos-lab-provision",
        "--repo",
        "https://helm.releases.hashicorp.com",
        "--version",
        "0.34.1",
        "--namespace",
        "vault",
        "--create-namespace",
        "--values",
        "/opt/bromigos-lab/helm/vault.yaml",
        "--timeout",
        "10m"
      ]
    },
    "changed_when": false,
    "environment": {
      "KUBECONFIG": "/etc/rancher/k3s/k3s.yaml"
    },
    "name": "Converge vault"
  },
  {
    "ansible.builtin.copy": {
      "dest": "/opt/bromigos-lab/helm/argocd.yaml",
      "mode": "0600",
      "src": "{{ playbook_dir }}/../../helm/argocd/values.yaml"
    },
    "name": "Copy argocd values"
  },
  {
    "ansible.builtin.command": {
      "argv": [
        "helm",
        "status",
        "argocd",
        "--namespace",
        "argocd",
        "--output",
        "json"
      ]
    },
    "changed_when": false,
    "environment": {
      "KUBECONFIG": "/etc/rancher/k3s/k3s.yaml"
    },
    "failed_when": false,
    "name": "Read argocd release ownership",
    "register": "existing_release"
  },
  {
    "ansible.builtin.assert": {
      "fail_msg": "This Helm release belongs to another installer; use a fresh namespace or cluster",
      "that": [
        "existing_release.rc != 0 or (existing_release.stdout | from_json).info.description == 'bromigos-lab-provision'"
      ]
    },
    "name": "Refuse to take over an existing argocd release"
  },
  {
    "ansible.builtin.command": {
      "argv": [
        "helm",
        "upgrade",
        "--install",
        "argocd",
        "argo-cd",
        "--description",
        "bromigos-lab-provision",
        "--repo",
        "https://argoproj.github.io/argo-helm",
        "--version",
        "10.10.2",
        "--namespace",
        "argocd",
        "--create-namespace",
        "--values",
        "/opt/bromigos-lab/helm/argocd.yaml",
        "--timeout",
        "10m",
        "--wait"
      ]
    },
    "changed_when": false,
    "environment": {
      "KUBECONFIG": "/etc/rancher/k3s/k3s.yaml"
    },
    "name": "Converge argocd"
  }
]

ansible/roles/k3s/tasks/main.json:
[
  {
    "ansible.builtin.package": {
      "name": [
        "curl",
        "iptables"
      ],
      "state": "present"
    },
    "name": "Install required networking tools"
  },
  {
    "ansible.builtin.get_url": {
      "dest": "/opt/bromigos-k3s-install.sh",
      "mode": "0700",
      "url": "https://get.k3s.io"
    },
    "name": "Download the k3s installer"
  },
  {
    "ansible.builtin.command": {
      "cmd": "/opt/bromigos-k3s-install.sh server --disable traefik --disable servicelb --secrets-encryption",
      "creates": "/etc/rancher/k3s/k3s.yaml"
    },
    "environment": {
      "INSTALL_K3S_VERSION": "v1.37.1+k3s1"
    },
    "name": "Install the pinned single-node cluster"
  },
  {
    "ansible.builtin.systemd": {
      "enabled": true,
      "name": "k3s",
      "state": "started"
    },
    "name": "Keep k3s running"
  }
]

